package lr2touch;
import bms.player.beatoraja.*;import bms.player.beatoraja.play.BMSPlayer;import bms.player.beatoraja.select.MusicSelector;import bms.player.beatoraja.select.bar.SongBar;import bms.player.beatoraja.song.SongData;
import java.awt.*;import java.net.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import javax.swing.*;

/** LAN client: sockets, hashing and clocks stay off the game and Swing threads. */
public final class BattleClient extends JPanel implements AutoCloseable {
 static volatile BattleClient active;final Touch ui;final JTextField host=new JTextField("192.168.1.10"),port=new JTextField("24880"),code=new JTextField();final JLabel connection=Touch.label("DISCONNECTED",26,0),opponent=Touch.label("OPPONENT: —",26,0),sync=Touch.label("CLOCK: NOT CHECKED",24,0),roundLabel=Touch.label("Select a song in the game, then offer it here",24,0);
 final ScheduledExecutorService network=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"Battle-client");t.setDaemon(true);return t;});final ExecutorService files=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"Battle-hash");t.setDaemon(true);return t;});final AtomicBoolean sampleQueued=new AtomicBoolean();volatile BattleWire wire;volatile Round round;volatile BattleClock clock=new BattleClock();volatile long lastServer;volatile String status="DISCONNECTED";volatile boolean closed,connecting;volatile int slot;volatile int generation;long lastPing;volatile String proposal="";javax.swing.Timer repaintTimer;
 static final class Round {final String id,hash,hold;volatile String error="";volatile SongData song;volatile boolean cancelled,loaded,navigated,ready,readySent,committed,started,finished;volatile long deadline,offset,startedServer;volatile int ex;volatile Object player;Round(String id,String hash,String hold){this.id=id;this.hash=hash;this.hold=hold;}}
 BattleClient(Touch ui){super(new BorderLayout(16,20));this.ui=ui;setOpaque(false);active=this;JPanel body=Touch.panel(new GridLayout(0,1,0,14));JPanel fields=Touch.panel(new GridLayout(1,3,14,0));fields.add(edit("Server IP",host));fields.add(edit("Port",port));fields.add(edit("Room code",code));body.add(fields);JPanel actions=Touch.panel(new GridLayout(1,3,14,0));actions.add(ui.button("Connect",this::connect));actions.add(ui.button("Disconnect",this::disconnect));actions.add(ui.button("Offer selected song",this::offer));body.add(actions);body.add(connection);body.add(opponent);body.add(sync);body.add(roundLabel);body.add(Touch.label("CONNECTING ALLOWS THE HOST TO LOAD AND START AN AGREED CHART.",24,0));body.add(Touch.label("Both clients need identical game builds, chart folders and hold mode.",24,0));body.add(Touch.label("The host checks synchronization and schedules the start.",24,0));TouchWidgets.stack(body);add(TouchWidgets.scroll(body));host.setText(ui.settings.getProperty("battleHost","192.168.1.10"));port.setText(ui.settings.getProperty("battlePort","24880"));repaintTimer=new javax.swing.Timer(250,e->{connection.setText(status);sync.setText(clock.count==0?"CLOCK: MEASURING WHEN CONNECTED":String.format(Locale.ROOT,"CLOCK %s · RTT %.2f MS · EST. ERROR ±%.2f MS",clock.good()?"READY":"WAIT",clock.rtt/1e6,clock.uncertainty/1e6));});repaintTimer.start();network.scheduleWithFixedDelay(this::tick,0,100,TimeUnit.MILLISECONDS);}
 JPanel edit(String title,JTextField field){JPanel p=Touch.panel(new BorderLayout(8,0));p.add(field);p.add(ui.button("Edit",()->TouchWidgets.text(ui,title,field)),BorderLayout.EAST);return ui.labeled(title,p);}
 void connect(){if(connecting||wire!=null&&!wire.closed)return;if(Touch.preview||!(ui.attachedMain instanceof MainController)){status="START LR2ORAJA BEFORE CONNECTING";return;}String address=host.getText().trim(),pin=code.getText().trim();int number;try{number=Integer.parseInt(port.getText().trim());if(number<1||number>65535||address.isBlank()||!pin.matches("[0-9]{6}"))throw new Exception();}catch(Exception e){status="ENTER SERVER IP, PORT AND SIX-DIGIT ROOM CODE";return;}ui.settings.setProperty("battleHost",address);ui.settings.setProperty("battlePort",""+number);ui.save();final int attempt=++generation;connecting=true;status="CONNECTING / CHECKING GAME BUILD";files.submit(()->{Socket socket=new Socket();try{Class.forName("bms.player.beatoraja.play.BMSPlayer");if(!BattleHooks.installed)throw new IOException("Unsupported game start hook — launch through the supplied launcher");String build=sha(Paths.get(MainController.class.getProtectionDomain().getCodeSource().getLocation().toURI()));if(closed||attempt!=generation)throw new IOException("Cancelled");socket.connect(new InetSocketAddress(address,number),4000);if(socket.getInetAddress().isAnyLocalAddress())throw new IOException("Invalid host");if(closed||attempt!=generation)throw new IOException("Cancelled");BattleWire[] holder=new BattleWire[1];BattleWire session=new BattleWire(socket,v->{if(wire==holder[0])receive(v);},()->{if(wire==holder[0])lost();});holder[0]=session;wire=session;clock=new BattleClock();lastServer=System.nanoTime();session.start();String name=((MainController)ui.attachedMain).getPlayerConfig().getName();session.send("HELLO",BattleServer.VERSION,pin,BattleWire.clean(name),build);}catch(Exception e){try{socket.close();}catch(Exception ignored){}if(attempt==generation)status="CONNECTION FAILED: "+e.getMessage();}finally{if(attempt==generation)connecting=false;}});}
 void send(String... values){BattleWire w=wire;if(w!=null&&!w.closed)w.send(values);}
 void receive(String[] v){lastServer=System.nanoTime();try{switch(v[0]){
  case "WELCOME":slot=Integer.parseInt(v[1]);status="CONNECTED AS PLAYER "+slot;break;
  case "PONG":clock.accept(Long.parseLong(v[1]),Long.parseLong(v[2]),Long.parseLong(v[3]),System.nanoTime());break;
  case "STATE":status=v[1]+" · "+v[2];String name=v[slot==1?4:3];SwingUtilities.invokeLater(()->opponent.setText("OPPONENT: "+name));break;
  case "CHECK":if(round!=null&&round.started&&!round.finished&&!(ui.attachedMain instanceof MainController&&((MainController)ui.attachedMain).getCurrentState() instanceof MusicSelector)){send("ERROR",v[1],"Finish the current chart and return to song selection first");break;}if(round!=null&&!round.finished&&!round.started)cancel("Replacing round");if(!v[2].matches("[0-9a-fA-F]{64}"))throw new IOException("Invalid chart hash");Round r=new Round(v[1],v[2],v[3]);round=r;files.submit(()->check(r));break;
  case "LOAD":Round load=matching(v);if(load!=null&&load.song!=null&&!load.loaded){load.loaded=true;ui.postRaw(()->load(load));}break;
  case "ARM":Round arm=matching(v);if(arm==null||!arm.ready||!clock.good())throw new IOException("Not ready or clock unstable");arm.offset=clock.offset;arm.deadline=Long.parseLong(v[2])-arm.offset;long lead=arm.deadline-System.nanoTime();if(lead<2_000_000_000L||lead>10_000_000_000L)throw new IOException("Invalid start deadline");send("ARMED",arm.id);break;
  case "COMMIT":Round commit=matching(v);if(commit==null||commit.deadline-System.nanoTime()<1_000_000_000L||!clock.good())throw new IOException("Late/unstable start");commit.committed=true;send("COMMITTED",commit.id);break;
  case "ABORT":if(matching(v)!=null)cancel(v[2]);break;
  default:throw new IOException("Unknown server message");
 }}catch(Exception e){Round r=round;if(r!=null)r.error=e.getMessage();else disconnect();}}
 Round matching(String[] v){Round r=round;return r!=null&&r.id.equals(v[1])?r:null;}
 void offer(){if(wire==null||wire.closed){status="CONNECT TO THE SERVER FIRST";return;}ui.command(o->{MainController main=(MainController)o;if(!(main.getCurrentState() instanceof MusicSelector)){ui.message("Return to song selection to offer a chart");return;}Object bar=((MusicSelector)main.getCurrentState()).getBarManager().getSelected();if(!(bar instanceof SongBar)){ui.message("Select an individual song first");return;}SongData song=((SongBar)bar).getSongData();proposal=song.getSha256();String table="";boolean inTable=false;for(Object directory:((MusicSelector)main.getCurrentState()).getBarManager().getDirectory()){String kind=directory.getClass().getSimpleName();if(kind.equals("TableBar")){table=String.valueOf(Touch.call(directory,"getTitle"));inTable=true;}else if(inTable&&kind.equals("HashBar"))table+=" "+Touch.call(directory,"getTitle");}send("OFFER",song.getSha256(),BattleWire.clean(song.getTitle()),BattleWire.clean(song.getArtist()),table,""+main.getPlayerConfig().getLnmode());SwingUtilities.invokeLater(()->roundLabel.setText("OFFERED: "+song.getTitle()));});}
 void check(Round r){try{MainController main=(MainController)ui.attachedMain;if(!(main.getCurrentState() instanceof MusicSelector))throw new IOException("Return to song selection first");if(main.getPlayerConfig().getLnmode()!=Integer.parseInt(r.hold))throw new IOException("Hold mode differs; choose the same LN / CN / HCN mode");SongData[] songs=main.getSongDatabase().getSongDatas("sha256",r.hash);if(songs.length==0)throw new IOException("Chart is not in this client's song database");SongData song=null;Path chart=null;String failedPath="";for(SongData candidate:songs){try{Path candidatePath=Paths.get(candidate.getPath()).toRealPath();if(Files.isRegularFile(candidatePath)&&sha(candidatePath).equalsIgnoreCase(r.hash)){song=candidate;chart=candidatePath;break;}failedPath=candidate.getPath();}catch(Exception pathError){failedPath=candidate.getPath();}}if(song==null||chart==null)throw new IOException("Matching chart file is missing or unavailable on this PC: "+failedPath+". Refresh the song database and check the chart path.");if(Files.size(chart)>16*1024*1024)throw new IOException("Chart too large");String text=new String(Files.readAllBytes(chart),StandardCharsets.ISO_8859_1);if(java.util.regex.Pattern.compile("(?im)^\\s*#(?:RANDOM|SETRANDOM)\\b").matcher(text).find())throw new IOException("#RANDOM charts are not supported in this first battle build");checkAssetPaths(chart,text);String manifest=manifest(chart.getParent(),()->round==r&&!closed&&!r.cancelled);if(round!=r)return;final SongData selectedSong=song;r.song=selectedSong;send("CHECKED",r.id,manifest,r.hold);SwingUtilities.invokeLater(()->roundLabel.setText("MATCHED: "+selectedSong.getTitle()+" · WAITING FOR HOST"));}catch(Exception e){if(round==r)r.error=e.getMessage();}}
 void load(Round r){if(round!=r)return;try{MainController main=(MainController)ui.attachedMain;if(!(main.getCurrentState() instanceof MusicSelector))throw new IOException("Not in song selection");if(main.getPlayerConfig().getLnmode()!=Integer.parseInt(r.hold))throw new IOException("Hold mode changed");if(bms.player.beatoraja.modmenu.FreqTrainerMenu.isFreqTrainerEnabled()||bms.player.beatoraja.modmenu.JudgeTrainer.isActive())throw new IOException("Disable rate modifier and judge trainer for battle");PlayerResource resource=main.getPlayerResource();resource.clear();resource.setSongdata(r.song);if(!resource.setBMSFile(Paths.get(r.song.getPath()),BMSPlayerMode.PLAY))throw new IOException("Game could not load chart");main.changeState(MainState.MainStateType.DECIDE);r.navigated=true;ui.focusGame();}catch(Exception e){r.error=e.getMessage();}}
 public static int gate(int normal,Object player){BattleClient client=active;if(client==null)return normal;Round r=client.round;if(r==null||!r.loaded||!r.navigated||r.started||r.finished)return normal;if(r.player==null)r.player=player;if(r.player!=player){r.error="Unexpected gameplay instance";return Integer.MAX_VALUE;}if(r.started)return normal;r.ready=true;if(!r.error.isEmpty()||!r.committed||r.deadline==0)return Integer.MAX_VALUE;long now=System.nanoTime();if(now<r.deadline)return Integer.MAX_VALUE;if(now-client.lastServer>1_500_000_000L||now-r.deadline>40_000_000L){r.error="Start missed or server heartbeat stale; round cancelled";return Integer.MAX_VALUE;}r.started=true;r.startedServer=now+r.offset;return -1;}
 int ticks;void tick(){if(closed)return;try{BattleWire w=wire;if(w==null||w.closed)return;long now=System.nanoTime();if(now-lastPing>=250_000_000L){lastPing=now;send("PING",""+now);send("SYNC",""+clock.rtt,""+clock.uncertainty,""+clock.count);}Round r=round;if(r==null||r.cancelled)return;if(!r.error.isEmpty()){String error=r.error;send("ERROR",r.id,error);cancel(error);return;}if((++ticks%2)==0&&sampleQueued.compareAndSet(false,true))ui.postRaw(()->{try{sample(r);}finally{sampleQueued.set(false);}});}catch(Exception e){status="BATTLE ERROR: "+e.getMessage();}}
 void sample(Round r){if(round!=r||r.finished||!(ui.attachedMain instanceof MainController))return;MainController main=(MainController)ui.attachedMain;MainState state=main.getCurrentState();if(state instanceof BMSPlayer){BMSPlayer p=(BMSPlayer)state;if(r.ready&&!r.readySent){r.readySent=true;SongData song=main.getPlayerResource().getSongdata();send("READY",r.id,""+main.getPlayerResource().getBMSModel().getTotalNotes(),BattleWire.clean(song.getTitle()),BattleWire.clean(song.getArtist()),BattleWire.clean(main.getPlayerResource().getTableFullname()));}if(r.started&&p.getJudgeManager()!=null&&p.getJudgeManager().getScoreData()!=null){r.ex=p.getJudgeManager().getScoreData().getExscore();r.finished=p.getState()!=BMSPlayer.STATE_PLAY;} }else if(r.navigated&&!r.started&&!(state!=null&&state.getClass().getSimpleName().equals("MusicDecide"))){r.error="Player left the loading / ready screen";}else if(r.started)r.finished=true;if(r.started)send("SCORE",r.id,""+r.ex,""+r.startedServer,r.finished?"FINISHED":"PLAYING");}
 void cancel(String reason){Round r=round;if(r!=null){r.cancelled=true;r.error=reason;}status="ROUND CANCELLED: "+reason;if(r!=null&&r.navigated&&!r.started)ui.postRaw(()->{if(round!=r)return;try{MainController main=(MainController)ui.attachedMain;MainState state=main.getCurrentState();if(state instanceof BMSPlayer||state.getClass().getSimpleName().equals("MusicDecide"))main.changeState(MainState.MainStateType.MUSICSELECT);if(round==r)round=null;}catch(Exception e){ui.message("Battle cancelled; use Back to leave the waiting screen");}});}
 void lost(){cancel("Disconnected from host");status="DISCONNECTED · CHECK ROOM CODE / NETWORK";}
 void disconnect(){generation++;connecting=false;BattleWire w=wire;wire=null;if(w!=null)w.close();cancel("Disconnected");status="DISCONNECTED";}
 public void close(){closed=true;disconnect();network.shutdownNow();files.shutdownNow();repaintTimer.stop();if(active==this)active=null;}
 static void checkAssetPaths(Path chart,String text)throws Exception{
  java.util.List<String> names=new ArrayList<>();
  if(chart.getFileName().toString().toLowerCase(Locale.ROOT).endsWith(".bmson")){var json=ProfileRestart.JSON.readTree(chart.toFile());for(var channel:json.path("sound_channels"))names.add(channel.path("name").asText());for(var image:json.path("bga").path("bga_header"))names.add(image.path("name").asText());}
  else{var m=java.util.regex.Pattern.compile("(?im)^\\s*#(?:WAV[0-9A-Z]{2}|BMP[0-9A-Z]{2}|STAGEFILE|BANNER|BACKBMP|PREVIEW)\\s+([^\\r\\n]+)").matcher(text);while(m.find())names.add(m.group(1).trim());}
  Path root=chart.getParent().toAbsolutePath().normalize();for(String name:names){String path=name.replace('\\','/');if(path.contains(":")||path.startsWith("/")||!root.resolve(path).normalize().startsWith(root))throw new IOException("Chart references media outside its folder; use a self-contained chart copy");}
 }
 static String sha(Path p)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=Files.newInputStream(p)){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedException();digest.update(buffer,0,n);}}return HexFormat.of().formatHex(digest.digest());}
 static String manifest(Path folder,java.util.function.BooleanSupplier valid)throws Exception{ArrayList<Path> paths=new ArrayList<>();try(var walk=Files.walk(folder)){Iterator<Path> it=walk.iterator();while(it.hasNext()){Path p=it.next();if(Files.isSymbolicLink(p))throw new IOException("Linked chart assets are not supported");if(Files.isRegularFile(p)){paths.add(p);if(paths.size()>15000)throw new IOException("Chart folder has too many files");}}}paths.sort(Comparator.comparing(p->folder.relativize(p).toString().replace('\\','/')));MessageDigest digest=MessageDigest.getInstance("SHA-256");long size=0;for(Path p:paths){if(!valid.getAsBoolean())throw new InterruptedException();size+=Files.size(p);if(size>8L*1024*1024*1024)throw new IOException("Chart folder exceeds 8 GB");digest.update(folder.relativize(p).toString().replace('\\','/').getBytes(StandardCharsets.UTF_8));digest.update((byte)0);digest.update(sha(p).getBytes(StandardCharsets.US_ASCII));}return HexFormat.of().formatHex(digest.digest());}
}
